#!/usr/bin/env python3
"""Container-only integration checks; all fixture data is generated by CI."""
import hashlib
import http.client
import json
from pathlib import Path
import time
import uuid

key = json.loads(Path("/fixtures/keys.json").read_text())["consumers"][0]["keys"][0]
data = Path("/fixtures/input.mp4").read_bytes()


def request(method, path, body=None, extra=None):
    connection = http.client.HTTPConnection("ffmpeg", 8080, timeout=10)
    headers = {"Authorization": "Bearer " + key}
    headers.update(extra or {})
    connection.request(method, path, body, headers)
    response = connection.getresponse()
    code, headers, data = response.status, dict(response.getheaders()), response.read()
    connection.close()
    return code, headers, data


for operation, output, parameters in [
    ("metadata", "json", {}),
    ("transcode", "mp4", {"width": 32, "height": 32}),
    ("transcode", "webm", {}),
    ("thumbnail", "png", {"width": 32, "height": 32, "timestamp_seconds": 0}),
    ("extract_audio", "mp3", {}),
    ("trim", "mp4", {"start_seconds": 0, "duration_seconds": 0.3}),
    ("remux", "mp4", {}),
    ("transcode", "mp4", {"audio_mode": "remove", "max_dimension": 32, "max_fps": 5, "max_bitrate_kbps": 200}),
    ("remux", "mp4", {"audio_mode": "remove"}),
]:
    boundary = uuid.uuid4().hex
    spec = {"operation": operation, "parameters": parameters, "output_format": output,
            "input": {"size_bytes": len(data), "sha256": hashlib.sha256(data).hexdigest()}}
    body = (f"--{boundary}\r\nContent-Disposition: form-data; name=\"request\"\r\nContent-Type: application/json\r\n\r\n"
            + json.dumps(spec) + f"\r\n--{boundary}\r\nContent-Disposition: form-data; name=\"file\"; filename=\"input\"\r\n\r\n").encode()
    body += data + f"\r\n--{boundary}--\r\n".encode()
    code, _, raw = request("POST", "/v1/jobs", body, {"Content-Type": "multipart/form-data; boundary=" + boundary, "Idempotency-Key": uuid.uuid4().hex})
    assert code == 202, (code, raw)
    job = json.loads(raw)
    for _ in range(120):
        code, _, raw = request("GET", job["status_url"])
        assert code == 200, (code, raw)
        job = json.loads(raw)
        if job["status"] not in ("queued", "processing"):
            break
        time.sleep(0.5)
    assert job["status"] == "completed", job
    code, _, result = request("GET", job["download_url"])
    assert code == 200 and hashlib.sha256(result).hexdigest() == job["result"]["sha256"]
    code, _, part = request("GET", job["download_url"], extra={"Range": "bytes=0-3"})
    assert code == 206 and part == result[:4]
    code, _, html = request("GET", job["status_url"], extra={"Accept": "text/html"})
    assert code == 200 and b"Download result" in html
    assert request("DELETE", job["status_url"])[0] == 204
    assert request("GET", job["status_url"])[0] == 410
    print(operation, output, "passed")
assert request("GET", "/v1/capabilities", extra={"Authorization": ""})[0] == 401
code, _, raw = request("GET", "/v1/capabilities")
caps = json.loads(raw)
assert code == 200 and "audio_mode" in caps["parameters"]["transcode"] and caps["limits"]["process_timeout_seconds"] > 0, caps
print("Container API and sandbox startup checks passed.")
